package alcaldedigital.carrera;

import alcaldedigital.compartido.carrera.*;
import alcaldedigital.compartido.carrera.EstadoCarrera.*;
import alcaldedigital.compartido.modelo.*;
import alcaldedigital.servidor.carrera.*;
import java.util.*;import java.io.*;import java.nio.file.*;
import org.junit.jupiter.api.Test;import org.junit.jupiter.api.io.TempDir;
import static org.junit.jupiter.api.Assertions.*;

class MotorCarreraTest {
    @TempDir Path tmp;
    static MotorCarrera nuevo(int humanos,Dificultad d){var c=EstadoCiudad.inicial();var m=new MotorCarrera(2026,humanos,d,c,EstadoElectoral.inicial(c),true);for(int r=0;r<2;r++)m.conectar(r,true);return m;}
    static void empezar(MotorCarrera m){for(int r=0;r<2;r++)m.orden(r,0,false,"LISTO",0);for(int i=0;i<40&&m.vista().fase()!=Fase.CUENTA;i++)for(int r=0;r<2;r++)m.orden(r,0,false,"CONTINUAR",0);assertEquals(Fase.CUENTA,m.vista().fase());for(int i=0;i<180;i++)m.paso();assertEquals(Fase.CARRERA,m.vista().fase());}
    static Vista copiar(Vista v,Fase f,int reloj,Corredor[] c,List<Objeto> objetos){return new Vista(v.id(),v.semilla(),v.tick(),f,reloj,0,v.dificultad(),v.humanos(),false,v.ganador(),c,objetos,v.grupos(),v.electoral(),v.ciudad(),v.base(),v.historial(),v.publicaciones(),v.ondas(),v.mensaje());}
    static Corredor corredor(Corredor c,float x,float y,Evento e,boolean asistido){return new Corredor(x,y,c.impulso(),c.velocidad(),c.puntos(),c.reputacion(),c.escudo(),c.frenado(),c.turbo(),c.habilidad(),c.avisoAtaque(),c.objetivoAtaque(),c.ultimoPulso(),c.pulsos(),e==null?c.siguienteEvento():e.indice(),true,true,false,asistido,e);}
    static MotorCarrera conEvento(Noticia tipo,int rol){var m=nuevo(3,Dificultad.NORMAL);empezar(m);int objetivo=MotorCarrera.HITOS[tipo.ordinal()];m.orden(rol,0,true,"",0);while(m.vista().corredores()[rol].distancia()<objetivo){if(m.vista().corredores()[rol].evento()!=null)m.orden(rol,0,true,"ACCION",2);m.orden(rol,0,true,"",0);m.paso();}assertEquals(tipo,m.vista().corredores()[rol].evento().tipo());return m;}
    static byte[] bytes(Vista v)throws Exception{var b=new ByteArrayOutputStream();EstadoCarrera.escribir(new DataOutputStream(b),v);return b.toByteArray();}
    @Test void historiaYConfirmacionesSoloRequierenRolesHumanos(){for(int humanos:new int[]{1,2,3}){var m=nuevo(humanos,Dificultad.NORMAL);for(int r=0;r<2;r++)m.orden(r,0,false,"LISTO",0);assertEquals(Fase.ANUNCIO,m.vista().fase());int rol=humanos==2?1:0;m.orden(rol,0,false,"CONTINUAR",0);assertEquals(humanos==3?0:1,m.vista().linea());}}
    @Test void noHayMovimientoDuranteHistoriaNiAntesDeLaSalida(){var m=nuevo(1,Dificultad.NORMAL);m.orden(0,0,false,"LISTO",0);m.orden(0,1,true,"PULSO",0);for(int i=0;i<200;i++)m.paso();assertEquals(0,m.vista().corredores()[0].distancia());assertEquals(0,m.vista().corredores()[0].pulsos());}
    @Test void pulsarRapidamenteNoSuperaLaCadenciaNiLaVelocidad(){var m=nuevo(3,Dificultad.DIFICIL);empezar(m);for(int i=0;i<360;i++){for(int n=0;n<20;n++)m.orden(0,0,false,"PULSO",0);m.orden(1,0,true,"",0);m.paso();for(var c:m.vista().corredores())assertTrue(c.velocidad()<=MotorCarrera.VELOCIDAD_MAX);}
        assertTrue(m.vista().corredores()[0].pulsos()<=37);assertTrue(m.vista().corredores()[0].distancia()>600);assertTrue(m.vista().corredores()[1].pulsos()>20);}
    @Test void mantenerYPulsarSonOpcionesRealesYSinRepeticionInvoluntaria(){var m=nuevo(3,Dificultad.NORMAL);empezar(m);m.orden(0,0,false,"ASISTENCIA",0); // Fuera de pausa no cambia la modalidad.
        m.orden(0,0,false,"PAUSA",0);m.orden(0,0,false,"ASISTENCIA",0);m.orden(0,0,false,"REANUDAR",0);
        for(int i=0;i<120;i++){m.orden(0,0,true,"",0);m.orden(1,0,true,"",0);m.paso();}assertEquals(0,m.vista().corredores()[0].pulsos());assertTrue(m.vista().corredores()[1].pulsos()>=9);}
    @Test void contrastarEliminaDelAVLYPropagaUnaAclaracion(){var m=conEvento(Noticia.ATAJO,0);long id=m.publicaciones.recorrer("inverso").stream().filter(p->p.autor().equals("Periodista")).findFirst().orElseThrow().id();int rep=m.vista().corredores()[0].reputacion();m.orden(0,0,false,"ACCION",0);
        assertNull(m.publicaciones.buscar(id));assertEquals(rep+8,m.vista().corredores()[0].reputacion());assertFalse(m.vista().ondas().isEmpty());for(int i=0;i<140;i++)m.paso();assertTrue(Arrays.stream(m.vista().grupos()).anyMatch(x->x==3));assertTrue(m.vista().ciudad()[5]<m.vista().base()[5]);}
    @Test void difundirRumorAfectaAlRivalConAvisoYALaCiudad(){var m=conEvento(Noticia.RUMOR,0);int reputacion=m.vista().corredores()[0].reputacion();m.orden(0,0,false,"ACCION",1);assertEquals(60,m.vista().corredores()[1].avisoAtaque());assertTrue(m.vista().ciudad()[5]>m.vista().base()[5]);assertTrue(m.vista().corredores()[0].reputacion()<reputacion);
        m.orden(1,-1,false,"",0);for(int i=0;i<60;i++)m.paso();assertEquals(0,m.vista().corredores()[1].frenado());}
    @Test void pactoNecesitaConfirmacionYNoSeBorraConReputacion(){var m=conEvento(Noticia.PACTO,0);m.orden(0,0,false,"ACCION",1);assertFalse(m.vista().electoral().juanCorrupto());assertTrue(m.vista().corredores()[0].evento().advertencia());m.orden(0,0,false,"ACCION",3);assertTrue(m.vista().electoral().juanCorrupto());assertFalse(m.vista().electoral().elegible(0));
        assertNotEquals(0,m.vista().electoral().liderProvisional());var mejor=m.vista().electoral().aplicar(0,100,100,100,0,100,"Mejoró su reputación",false);assertTrue(mejor.juanCorrupto());assertNotEquals(0,mejor.liderProvisional());}
    @Test void leerElPactoYRechazarloConservaLaElegibilidad(){var m=conEvento(Noticia.PACTO,1);m.orden(1,0,false,"ACCION",1);m.orden(1,0,false,"ACCION",0);assertFalse(m.vista().electoral().juanCorrupto());assertTrue(m.vista().electoral().elegible(0));assertNull(m.vista().corredores()[1].evento());}
    @Test void confirmacionFueraDeUnPactoAdvertidoNoTieneEfecto(){var m=conEvento(Noticia.PACTO,0);m.orden(0,0,false,"ACCION",3);assertFalse(m.vista().electoral().juanCorrupto());assertNotNull(m.vista().corredores()[0].evento());}
    @Test void periodistaContrastaMasRapidoEInfluencerLlegaAMasCiudadanos(){var periodista=conEvento(Noticia.ATAJO,0);var influencer=conEvento(Noticia.ATAJO,1);periodista.orden(0,0,false,"ACCION",0);influencer.orden(1,0,false,"ACCION",0);assertTrue(periodista.vista().corredores()[0].frenado()<influencer.vista().corredores()[1].frenado());assertEquals(3,periodista.vista().ondas().size());assertEquals(7,influencer.vista().ondas().size());}
    @Test void pausarCongelaObstaculosRivalesYTiempoDeNoticias(){var m=conEvento(Noticia.ATAJO,0);m.orden(0,1,true,"PAUSA",0);var v=m.vista();for(int i=0;i<600;i++){m.orden(1,1,true,"ACCION",1);m.paso();}assertEquals(v.tick(),m.vista().tick());assertArrayEquals(v.corredores(),m.vista().corredores());assertEquals(v.ondas(),m.vista().ondas());m.orden(0,1,true,"REANUDAR",0);float y=m.vista().corredores()[0].y();m.paso();assertEquals(y,m.vista().corredores()[0].y());}
    @Test void desconexionRequiereQueVuelvanAmbosAntesDeContinuar(){var m=nuevo(3,Dificultad.NORMAL);empezar(m);m.conectar(1,false);assertTrue(m.vista().pausa());m.orden(0,0,false,"REANUDAR",0);assertTrue(m.vista().pausa());m.conectar(1,true);m.orden(1,0,false,"REANUDAR",0);assertFalse(m.vista().pausa());}
    @Test void guardadoReproduceExactamenteNoticiasObjetosOndasYEleccion()throws Exception{var m=conEvento(Noticia.RUMOR,0);m.orden(0,0,false,"ACCION",1);for(int i=0;i<7;i++)m.paso();var g=new GuardadoCarrera(tmp.resolve("carrera.bin"));g.guardar(m);var r=g.cargar();assertArrayEquals(bytes(m.vista()),bytes(r.vista()));for(int i=0;i<100;i++){m.orden(0,-1,true,"",0);r.orden(0,-1,true,"",0);m.paso();r.paso();}assertArrayEquals(bytes(m.vista()),bytes(r.vista()));}
    @Test void escudoYPickupsFuncionanYSoloSeConsumenUnaVezPorRol(){var m=nuevo(3,Dificultad.NORMAL);empezar(m);var v=m.vista();var cs=v.corredores();cs[0]=corredor(cs[0],100,400,null,true);m=MotorCarrera.restaurar(copiar(v,Fase.CARRERA,0,cs,List.of(new Objeto(1,102,400,4,0,0))));m.paso();assertEquals(4,m.vista().corredores()[0].habilidad());m.orden(0,0,false,"USAR",0);assertEquals(240,m.vista().corredores()[0].escudo());assertEquals(0,m.vista().corredores()[0].habilidad());m.paso();assertEquals(0,m.vista().corredores()[0].habilidad());}
    @Test void recorridosTerminanConCPUYDosHumanosEnTodasLasDificultades(){int casos=0;for(var d:Dificultad.values())for(int humanos:new int[]{1,2,3}){
        var m=nuevo(humanos,d);empezar(m);for(int i=0;i<18000&&m.vista().fase()!=Fase.RESULTADO;i++){
            var v=m.vista();for(int r=0;r<2;r++)if(v.humano(r)){if(v.fase()==Fase.CARRERA){m.orden(r,0,true,"",0);if(v.corredores()[r].evento()!=null)m.orden(r,0,true,"ACCION",0);}else m.orden(r,0,false,"CONTINUAR",0);}m.paso();for(var c:m.vista().corredores())assertTrue(c.velocidad()<=MotorCarrera.VELOCIDAD_MAX);}
        assertEquals(Fase.RESULTADO,m.vista().fase(),d+" humanos="+humanos);assertTrue(m.vista().ganador()>=0);assertFalse(m.vista().electoral().juanCorrupto());assertTrue(m.vista().historial().size()>=5);casos++;
    }System.out.println("MISIÓN 7: "+casos+" recorridos completos con física real");}
}
